//! Source route-edge catalogue: schema, loading and validation.
//!
//! The asset is generated by the extraction pipeline from the disc and
//! cross-checked against the accepted `suikoden-route-transitions/1` packet. The
//! types here are a plain data model: they borrow their strings and slices from
//! the parsed JSON owner and never allocate after load.
const std = @import("std");
const validation = @import("validation");
const event_runtime = @import("event_runtime");

pub const schema = "suikoden-campaign-route-edges/1";
pub const max_json_bytes = 1024 * 1024;
pub const max_edges = 64;
pub const max_locations = 32;
pub const max_story_values = 32;
pub const max_effects = 16;
pub const source_base = 0x80010000;

pub const Source = struct {
    file: []const u8,
    lba: u32,
    size: u32,
    sha256: []const u8,
};
pub const CoordinateContracts = struct {
    half_cell: []const u8,
    field_pixel: []const u8,
    world_cell: []const u8,
};
pub const CoordinateDomain = enum { half_cell, field_pixel, world_cell };
pub const Coordinate = struct { domain: CoordinateDomain, x: i32, y: i32 };
pub const Rectangle = struct { domain: CoordinateDomain, x: i32, y: i32, w: i32, h: i32 };
pub const Direction = enum { up, down, left, right };
pub const PixelSize = struct { x: u16, y: u16 };
pub const Location = struct {
    id: []const u8,
    kind: enum { world_region, field_room },
    source_file: ?[]const u8 = null,
    source_room: ?u8 = null,
    world_region: ?u8 = null,
    identity: ?[]const u8 = null,
    export_package: ?[]const u8 = null,
    constructible: bool = true,
    pixel_size: ?PixelSize = null,
};
pub const StoryValue = struct {
    id: []const u8,
    storage: enum { scenario },
    byte_index: u8,
};
pub const Flag = event_runtime.Flag;
pub const Condition = event_runtime.Condition;
pub const EffectKind = enum {
    glyph_descriptor_display,
    queue_track,
    wait_text_queue_empty,
    descriptor_state_transition,
    open_dialogue_box,
    start_or_wait_dialogue,
    dialogue,
    wait_for_accept,
    close_dialogue_box,
    wait_event_flags_low2_clear,
    story_or,
    dialogue_cleanup,
    scroll_set_y,
    area_index_set,
};
pub const Effect = struct {
    kind: EffectKind,
    source_offset: u32,
    source_address: u32,
    operands: []const u8,
    flag: ?Flag = null,
    area_index: ?u16 = null,
    area_index_source_address: ?u32 = null,
    selector: ?u8 = null,
    parameter: ?u8 = null,
    mask: ?u8 = null,
    slot: ?u8 = null,
    layout: ?u8 = null,
};
pub const Trigger = struct {
    kind: enum { field_rectangle, world_point, ordinary_event },
    rectangle: ?Rectangle = null,
    point: ?Coordinate = null,
    direction: ?Direction = null,
};
pub const Origin = struct {
    location_id: []const u8,
    trigger: Trigger,
    event_flags_low2_clear: bool,
};
pub const Destination = struct {
    location_id: []const u8,
    source_spawn: Coordinate,
    spawn: Coordinate,
};
pub const ConstructionStory = enum { not_applicable, current_after_prefix_effects };
pub const Reconstruction = struct {
    required: bool,
    same_room: bool,
    construction_story: ConstructionStory,
};
pub const ContinuationKind = enum { field_ready, world_ready, ordinary_source_selection };
pub const Continuation = struct {
    kind: ContinuationKind,
    automatic_program_id: ?[]const u8 = null,
};
pub const Provenance = struct {
    file: []const u8,
    room: ?u8 = null,
    entity: ?u8 = null,
    entry_offset: ?u32 = null,
    predicate_offset: ?u32 = null,
    predicate_size: ?u8 = null,
    stream_offset: ?u32 = null,
    transition_offset: ?u32 = null,
    transition_operands: ?[]const u8 = null,
    world_table: ?[]const u8 = null,
    world_table_slot: ?[]const u8 = null,
    point_index: ?u8 = null,
    record_stride: ?u8 = null,
    anchor: ?[]const i32 = null,
    shared_route_id: ?[]const u8 = null,
    consumers: []const []const u8 = &.{},
};
pub const Edge = struct {
    id: []const u8,
    family: enum { field_doorway, world_exit, world_point_entry, ordinary_event },
    status: enum { proven },
    source_order: u8,
    origin: Origin,
    conditions: []const Condition,
    effects: []const Effect,
    destination: Destination,
    reconstruction: Reconstruction,
    continuation: Continuation,
    provenance: Provenance,
};
pub const Coverage = struct {
    edges: u16,
    field_doorways: u16,
    directional_field_doorways: u16,
    directionless_field_doorways: u16,
    world_point_entries: u16,
    world_exits: u16,
    ordinary_events: u16,
    conditioned_edges: u16,
    edges_with_prefix_effects: u16,
    unavailable_destinations: u16,
    unresolved: u16,
};
pub const Packet = struct {
    schema: []const u8,
    id: []const u8,
    content_sha256: []const u8,
    sources: []const Source,
    coordinate_contracts: CoordinateContracts,
    ordering: []const u8,
    story_values: []const StoryValue,
    locations: []const Location,
    edges: []Edge,
    coverage: Coverage,

    pub fn location(self: Packet, id: []const u8) ?Location {
        for (self.locations) |entry| if (std.mem.eql(u8, entry.id, id)) return entry;
        return null;
    }
    pub fn edge(self: Packet, id: []const u8) ?Edge {
        for (self.edges) |entry| if (std.mem.eql(u8, entry.id, id)) return entry;
        return null;
    }
    pub fn edgeIndex(self: Packet, id: []const u8) ?usize {
        for (self.edges, 0..) |entry, index| if (std.mem.eql(u8, entry.id, id)) return index;
        return null;
    }
    pub fn storyValue(self: Packet, id: []const u8) ?StoryValue {
        for (self.story_values) |entry| if (std.mem.eql(u8, entry.id, id)) return entry;
        return null;
    }
    pub fn destination(self: Packet, id: []const u8) ?Location {
        return self.location(id);
    }
};

pub fn scenarioIndex(id: []const u8) ?u8 {
    if (id.len != 13 or !std.mem.startsWith(u8, id, "scenario_")) return null;
    const value = std.fmt.parseInt(u16, id[9..], 10) catch return null;
    if (value >= 240) return null;
    return @intCast(value);
}

fn validId(id: []const u8) !void {
    if (!validation.isAsciiId(id, 96, "_")) return error.InvalidEdgeId;
}

fn validHash(hash: []const u8) !void {
    if (!validation.isHex64(hash)) return error.InvalidEdgeIdentity;
}

fn validCoordinate(value: Coordinate) !void {
    if (value.x < 0 or value.y < 0) return error.InvalidEdgeCoordinate;
    switch (value.domain) {
        .half_cell => if (value.x > 255 or value.y > 255) return error.InvalidEdgeCoordinate,
        .field_pixel => if (value.x > 2040 or value.y > 2040) return error.InvalidEdgeCoordinate,
        .world_cell => if (value.x > 4095 or value.y > 4095) return error.InvalidEdgeCoordinate,
    }
}

fn validateCondition(packet: Packet, condition: Condition) !void {
    if (condition.flag.mask == 0 or packet.storyValue(condition.flag.id) == null) return error.UnsupportedEdgePredicate;
}

fn validateEffect(packet: Packet, effect: Effect) !void {
    if (effect.source_address != source_base + effect.source_offset) return error.InvalidEdgeEffect;
    if (effect.operands.len > 8) return error.InvalidEdgeEffect;
    switch (effect.kind) {
        .story_or => {
            const value = effect.flag orelse return error.InvalidEdgeEffect;
            if (value.mask == 0 or packet.storyValue(value.id) == null) return error.UnknownEdgeStoryValue;
            if (effect.operands.len != 2) return error.InvalidEdgeEffect;
        },
        .area_index_set => {
            if (effect.operands.len != 1 or effect.area_index == null) return error.InvalidEdgeEffect;
        },
        .descriptor_state_transition => {
            if (effect.operands.len != 2 or effect.selector == null or effect.parameter == null) return error.InvalidEdgeEffect;
        },
        .open_dialogue_box, .start_or_wait_dialogue, .dialogue => if (effect.operands.len == 0) return error.InvalidEdgeEffect,
        else => {},
    }
}

fn checkFamily(packet: Packet, edge: Edge) !void {
    const origin = packet.location(edge.origin.location_id) orelse return error.UnknownEdgeOrigin;
    const destination = packet.location(edge.destination.location_id) orelse return error.UnknownEdgeDestination;
    const trigger = edge.origin.trigger;
    switch (edge.family) {
        .field_doorway => {
            if (trigger.kind != .field_rectangle or origin.kind != .field_room or destination.kind != .field_room) return error.InvalidEdgeFamily;
        },
        .world_exit => {
            if (trigger.kind != .field_rectangle or origin.kind != .field_room or destination.kind != .world_region) return error.InvalidEdgeFamily;
        },
        .world_point_entry => {
            if (trigger.kind != .world_point or origin.kind != .world_region or destination.kind != .field_room) return error.InvalidEdgeFamily;
        },
        .ordinary_event => {
            if (trigger.kind != .ordinary_event or origin.kind != .field_room or destination.kind != .field_room) return error.InvalidEdgeFamily;
        },
    }
    if (trigger.kind == .field_rectangle) {
        const rect = trigger.rectangle orelse return error.InvalidEdgeTrigger;
        if (rect.domain != .field_pixel or trigger.point != null) return error.InvalidEdgeTrigger;
        if (rect.w <= 0 or rect.h <= 0 or rect.w > 2040 or rect.h > 2040 or rect.x < 0 or rect.y < 0) return error.InvalidEdgeTrigger;
        try validCoordinate(.{ .domain = rect.domain, .x = rect.x, .y = rect.y });
        if (origin.pixel_size) |size| {
            if (rect.x + rect.w > size.x or rect.y + rect.h > size.y) return error.InvalidEdgeTrigger;
        }
        if (trigger.direction != null and edge.family != .field_doorway) return error.InvalidEdgeDirection;
    } else if (trigger.kind == .world_point) {
        const point = trigger.point orelse return error.InvalidEdgeTrigger;
        if (point.domain != .world_cell or trigger.rectangle != null or trigger.direction != null) return error.InvalidEdgeTrigger;
        try validCoordinate(point);
    } else {
        if (trigger.rectangle != null or trigger.point != null or trigger.direction != null) return error.InvalidEdgeTrigger;
    }
    const spawn_domain: CoordinateDomain = if (destination.kind == .world_region) .world_cell else .field_pixel;
    const source_domain: CoordinateDomain = if (destination.kind == .world_region) .world_cell else .half_cell;
    if (edge.destination.spawn.domain != spawn_domain or edge.destination.source_spawn.domain != source_domain) return error.InvalidEdgeCoordinateDomain;
    try validCoordinate(edge.destination.spawn);
    try validCoordinate(edge.destination.source_spawn);
    const scale: i32 = if (spawn_domain == .world_cell) 1 else 8;
    if (edge.destination.spawn.x != edge.destination.source_spawn.x * scale or
        edge.destination.spawn.y != edge.destination.source_spawn.y * scale) return error.EdgeCoordinateMismatch;
    const required = destination.kind == .field_room;
    if (edge.reconstruction.required != required) return error.InvalidEdgeReconstruction;
    if (edge.reconstruction.same_room != (edge.origin.location_id.len == edge.destination.location_id.len and
        std.mem.eql(u8, edge.origin.location_id, edge.destination.location_id))) return error.InvalidEdgeReconstruction;
    const expected_story: ConstructionStory = if (required) .current_after_prefix_effects else .not_applicable;
    if (edge.reconstruction.construction_story != expected_story) return error.InvalidEdgeReconstruction;
    if (edge.continuation.automatic_program_id != null) return error.UnsupportedEdgeContinuation;
    switch (edge.continuation.kind) {
        .world_ready => if (destination.kind != .world_region) return error.InvalidEdgeContinuation,
        .field_ready => if (destination.kind != .field_room or edge.reconstruction.same_room) return error.InvalidEdgeContinuation,
        .ordinary_source_selection => if (!edge.reconstruction.same_room) return error.InvalidEdgeContinuation,
    }
    if (edge.origin.event_flags_low2_clear != (origin.kind == .field_room)) return error.InvalidEdgeBarrier;
    for (edge.conditions) |condition| try validateCondition(packet, condition);
    for (edge.effects) |effect| try validateEffect(packet, effect);
}

pub fn validate(packet: Packet) !void {
    if (!std.mem.eql(u8, packet.schema, schema)) return error.UnsupportedEdgeSchema;
    try validId(packet.id);
    try validHash(packet.content_sha256);
    if (packet.sources.len == 0 or packet.sources.len > 8) return error.InvalidEdgeContent;
    if (packet.locations.len == 0 or packet.locations.len > max_locations) return error.InvalidEdgeContent;
    if (packet.edges.len == 0 or packet.edges.len > max_edges) return error.InvalidEdgeContent;
    if (packet.story_values.len == 0 or packet.story_values.len > max_story_values) return error.InvalidEdgeContent;
    for (packet.sources) |source| {
        if (source.file.len == 0 or source.size == 0) return error.InvalidEdgeSource;
        try validHash(source.sha256);
    }
    for (packet.locations, 0..) |location, index| {
        try validId(location.id);
        for (packet.locations[0..index]) |other| if (std.mem.eql(u8, location.id, other.id)) return error.DuplicateEdgeLocation;
        switch (location.kind) {
            .world_region => {
                if (location.world_region == null or location.source_room != null) return error.InvalidEdgeLocation;
            },
            .field_room => {
                if (location.source_room == null or location.world_region != null) return error.InvalidEdgeLocation;
                if (!std.mem.eql(u8, location.source_file orelse return error.InvalidEdgeLocation, "DATA/02_AREA.B/VB6.BIN")) return error.InvalidEdgeLocation;
                if (location.pixel_size == null) return error.InvalidEdgeLocation;
            },
        }
    }
    for (packet.story_values, 0..) |value, index| {
        try validId(value.id);
        const byte_index = scenarioIndex(value.id) orelse return error.InvalidEdgeStoryValue;
        if (byte_index != value.byte_index) return error.InvalidEdgeStoryValue;
        for (packet.story_values[0..index]) |other| {
            if (std.mem.eql(u8, value.id, other.id) or value.byte_index == other.byte_index) return error.DuplicateEdgeStoryValue;
        }
    }
    var previous_origin: []const u8 = "";
    var previous_order: u8 = 0;
    var first_edge = true;
    for (packet.edges, 0..) |edge, index| {
        try validId(edge.id);
        for (packet.edges[0..index]) |other| if (std.mem.eql(u8, edge.id, other.id)) return error.DuplicateEdge;
        if (edge.effects.len > max_effects) return error.TooManyEdgeEffects;
        try checkFamily(packet, edge);
        // Selection walks the array; an origin's edges must stay contiguous and
        // in ascending source order or a cue could be owned by a later edge.
        if (first_edge or !std.mem.eql(u8, edge.origin.location_id, previous_origin)) {
            previous_origin = edge.origin.location_id;
            previous_order = edge.source_order;
            first_edge = false;
        } else if (edge.source_order < previous_order) {
            return error.InvalidEdgeOrder;
        } else {
            previous_order = edge.source_order;
        }
    }
    const coverage = packet.coverage;
    if (coverage.edges != packet.edges.len) return error.InvalidEdgeCoverage;
    var field_doorways: u16 = 0;
    var directional: u16 = 0;
    var world_entries: u16 = 0;
    var world_exits: u16 = 0;
    var ordinary: u16 = 0;
    var conditioned: u16 = 0;
    var with_effects: u16 = 0;
    var unavailable: u16 = 0;
    for (packet.edges) |edge| {
        switch (edge.family) {
            .field_doorway => {
                field_doorways += 1;
                if (edge.origin.trigger.direction != null) directional += 1;
            },
            .world_point_entry => world_entries += 1,
            .world_exit => world_exits += 1,
            .ordinary_event => ordinary += 1,
        }
        if (edge.conditions.len > 0) conditioned += 1;
        if (edge.effects.len > 0) with_effects += 1;
        const destination = packet.location(edge.destination.location_id) orelse return error.UnknownEdgeDestination;
        if (!destination.constructible) unavailable += 1;
    }
    if (coverage.field_doorways != field_doorways or coverage.directional_field_doorways != directional or
        coverage.directionless_field_doorways != field_doorways - directional or
        coverage.world_point_entries != world_entries or coverage.world_exits != world_exits or
        coverage.ordinary_events != ordinary or coverage.conditioned_edges != conditioned or
        coverage.edges_with_prefix_effects != with_effects or coverage.unavailable_destinations != unavailable or
        coverage.unresolved != 0) return error.InvalidEdgeCoverage;
}

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Packet) {
    if (bytes.len > max_json_bytes) return error.EdgeContentTooLarge;
    const parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{ .allocate = .alloc_always });
    errdefer parsed.deinit();
    try validate(parsed.value);
    return parsed;
}
